// Build lookup table: normalized position name -> IMAGE_DATA key
const _imgKeyMap = (function(){
  const map = {};
  for(const key of Object.keys(IMAGE_DATA)){
    map[_normalizeImageKey(key)] = key;
  }
  return map;
})();

function _lookupPageStart(mapObj, posName){
  if(!mapObj || !posName) return null;
  if(Object.prototype.hasOwnProperty.call(mapObj, posName)) return Number(mapObj[posName]);
  const target = _normalizeImageKey(posName);
  for(const k of Object.keys(mapObj)){
    if(_normalizeImageKey(k) === target) return Number(mapObj[k]);
  }
  return null;
}

function _getImagesForPos(posRef){
  const lookupText = _collectPositionLookupText(posRef);
  if(!lookupText) return null;
  const lookupName = typeof posRef === 'string' ? posRef : (posRef && posRef.name) ? posRef.name : lookupText;
  const pageStart = Number(posRef && posRef.info && posRef.info.pageStart);
  if(pageStart){
    const isCh2Pos = _lookupPageStart(CH2_POSITION_PAGE_START, lookupName) === pageStart;
    const isCh3Pos = _lookupPageStart(CH3_POSITION_PAGE_START, lookupName) === pageStart;
    const isCh4Pos = _lookupPageStart(UPPER_LIMB_REFERENCE_PAGE_START, lookupName) === pageStart;
    const isCh5Pos = _lookupPageStart(CH5_POSITION_PAGE_START, lookupName) === pageStart;
    const isCh6Pos = _lookupPageStart(CH6_POSITION_PAGE_START, lookupName) === pageStart;
    const isCh7Pos = _lookupPageStart(CH7_POSITION_PAGE_START, lookupName) === pageStart;
    const isCh8Pos = _lookupPageStart(CH8_POSITION_PAGE_START, lookupName) === pageStart;
    const isCh9Pos = _lookupPageStart(CH9_POSITION_PAGE_START, lookupName) === pageStart;
    const isCh10Pos = _lookupPageStart(CH10_POSITION_PAGE_START, lookupName) === pageStart;
    if(isCh2Pos && CH2_PAGE_IMAGE_MAP && CH2_PAGE_IMAGE_MAP[pageStart] && CH2_PAGE_IMAGE_MAP[pageStart].length){
      return {positions: CH2_PAGE_IMAGE_MAP[pageStart].slice(), xrays: []};
    }
    if(isCh3Pos && CH3_PAGE_IMAGE_MAP && CH3_PAGE_IMAGE_MAP[pageStart] && CH3_PAGE_IMAGE_MAP[pageStart].length){
      return {positions: CH3_PAGE_IMAGE_MAP[pageStart].slice(), xrays: []};
    }
    if(isCh4Pos && CH4_PAGE_IMAGE_MAP && CH4_PAGE_IMAGE_MAP[pageStart] && CH4_PAGE_IMAGE_MAP[pageStart].length){
      return {positions: CH4_PAGE_IMAGE_MAP[pageStart].slice(), xrays: []};
    }
    if(isCh5Pos && CH5_PAGE_IMAGE_MAP && CH5_PAGE_IMAGE_MAP[pageStart] && CH5_PAGE_IMAGE_MAP[pageStart].length){
      return {positions: CH5_PAGE_IMAGE_MAP[pageStart].slice(), xrays: []};
    }
    if(isCh6Pos && CH6_PAGE_IMAGE_MAP && CH6_PAGE_IMAGE_MAP[pageStart] && CH6_PAGE_IMAGE_MAP[pageStart].length){
      return {positions: CH6_PAGE_IMAGE_MAP[pageStart].slice(), xrays: []};
    }
    if(isCh7Pos && CH7_PAGE_IMAGE_MAP && CH7_PAGE_IMAGE_MAP[pageStart] && CH7_PAGE_IMAGE_MAP[pageStart].length){
      return {positions: CH7_PAGE_IMAGE_MAP[pageStart].slice(), xrays: []};
    }
    if(isCh8Pos && CH8_PAGE_IMAGE_MAP && CH8_PAGE_IMAGE_MAP[pageStart] && CH8_PAGE_IMAGE_MAP[pageStart].length){
      return {positions: CH8_PAGE_IMAGE_MAP[pageStart].slice(), xrays: []};
    }
    if(isCh9Pos && CH9_PAGE_IMAGE_MAP && CH9_PAGE_IMAGE_MAP[pageStart] && CH9_PAGE_IMAGE_MAP[pageStart].length){
      return {positions: CH9_PAGE_IMAGE_MAP[pageStart].slice(), xrays: []};
    }
    if(isCh10Pos && CH10_PAGE_IMAGE_MAP && CH10_PAGE_IMAGE_MAP[pageStart] && CH10_PAGE_IMAGE_MAP[pageStart].length){
      return {positions: CH10_PAGE_IMAGE_MAP[pageStart].slice(), xrays: []};
    }
  }

  // 1. Check explicit name mapping first (highest priority)
  if(POSITION_IMAGE_MAP[lookupName] && IMAGE_DATA[POSITION_IMAGE_MAP[lookupName]]){
    return IMAGE_DATA[POSITION_IMAGE_MAP[lookupName]];
  }
  const n = _normalizeImageKey(lookupText);
  // 2. Try exact match via normalized key map
  if(_imgKeyMap[n]) return IMAGE_DATA[_imgKeyMap[n]];
  // 3. Try partial matches (position name contains key or key contains position name)
  let bestKey = null, bestScore = 0;
  for(const [kn, key] of Object.entries(_imgKeyMap)){
    const overlap = n.startsWith(kn) || kn.startsWith(n) || n.includes(kn) || kn.includes(n);
    if(overlap){
      const score = Math.min(kn.length, n.length) / Math.max(kn.length, n.length);
      if(score > bestScore){ bestScore = score; bestKey = key; }
    }
  }
  if(bestKey && bestScore >= 0.5) return IMAGE_DATA[bestKey];

  // 4. Try token-based matching from the descriptive text
  const tokens = lookupText.split(/[^a-z0-9]+/i).filter(Boolean).map(t => t.toLowerCase());
  if(tokens.length){
    let tokenBestKey = null;
    let tokenBestScore = 0;
    for(const [kn, key] of Object.entries(_imgKeyMap)){
      const knParts = kn.split('_').filter(Boolean);
      let score = 0;
      for(const token of tokens){
        if(token.length < 3) continue;
        if(kn.includes(token) || token.includes(knParts[0] || token)) score += 1;
      }
      const normalizedScore = score / Math.max(tokens.length, knParts.length || 1);
      if(normalizedScore > tokenBestScore){
        tokenBestScore = normalizedScore;
        tokenBestKey = key;
      }
    }
    if(tokenBestKey && tokenBestScore >= 0.35) return IMAGE_DATA[tokenBestKey];
  }

  return null;
}

let _offlineImageWarmupStarted = false;
function _warmupOfflineImages(){
  if(_offlineImageWarmupStarted) return;
  _offlineImageWarmupStarted = true;
  const queue = [];
  const seen = new Set();
  for(const entry of Object.values(IMAGE_DATA)){
    const files = [];
    if(Array.isArray(entry.positions)) files.push(...entry.positions);
    if(Array.isArray(entry.xrays)) files.push(...entry.xrays);
    for(const fname of files){
      if(!fname || seen.has(fname)) continue;
      seen.add(fname);
      queue.push(fname);
    }
  }

  if(!queue.length) return;

  const warmOne = (fname) => new Promise(resolve => {
    const img = new Image();
    img.decoding = 'async';
    img.onload = () => resolve();
    img.onerror = () => resolve();
    img.src = _resolveInlineImageSrc(fname);
  });

  const batchSize = 4;
  let index = 0;

  const pump = () => {
    const batch = queue.slice(index, index + batchSize);
    index += batch.length;
    if(!batch.length) return;
    Promise.all(batch.map(warmOne)).finally(() => {
      if(index < queue.length){
        if(typeof requestIdleCallback === 'function'){
          requestIdleCallback(pump, {timeout:1500});
        } else {
          setTimeout(pump, 120);
        }
      }
    });
  };

  warmOne(queue[0]).finally(() => {
    index = 1;
    if(index < queue.length){
      if(typeof requestIdleCallback === 'function'){
        requestIdleCallback(pump, {timeout:1500});
      } else {
        setTimeout(pump, 120);
      }
    }
  });
}


