// ── AUTO-GENERATE QUIZ from BOOK for positions without specific quiz questions ──
// This function generates basic questions from BOOK data for any chapter that has positions
(function _autoGenerateQuizFromBook(){
  function _makeOpts(correct, pool, n=4){
    const opts=new Set([correct]);
    const shuffled=[...pool].sort(()=>Math.random()-0.5);
    for(const o of shuffled){ if(opts.size>=n) break; if(o!==correct) opts.add(o); }
    while(opts.size<n) opts.add('None of the above');
    return [...opts].sort(()=>Math.random()-0.5);
  }

  Object.entries(BOOK).forEach(([chId,ch])=>{
    const process=(positions, qKey)=>{
      if(!positions||!positions.length) return;
      if(!QUIZ[qKey]) QUIZ[qKey]=[];
      // build a pool of position names for distractors
      const pool=positions.map(p=>p.name);
      positions.forEach(pos=>{
        const info=pos.info||{};
        const alreadyHas=QUIZ[qKey].some(q=>
          q.questionText && q.questionText.includes(pos.name) && q.questionText.length<200
        );
        if(alreadyHas) return; // skip if already has a direct question

        // Generate CR question
        if(info.cr && info.cr.length>5){
          const crOpts=[
            info.cr,
            'Perpendicular to IR at T7',
            '15° cephalad to midpoint',
            'Perpendicular, 2 inches below CR landmark',
          ].filter((v,i,a)=>a.indexOf(v)===i).slice(0,4);
          QUIZ[qKey].push({
            questionText:`For the **${pos.name}**, what is the correct CR (Central Ray) direction?`,
            xrayImg:'',
            options:crOpts.sort(()=>Math.random()-0.5),
            correct:info.cr
          });
        }

        // Generate kVp question
        if(info.kv && info.kv.length>3){
          QUIZ[qKey].push({
            questionText:`What is the kVp range for the **${pos.name}**?`,
            xrayImg:'',
            options:[info.kv,'110–125 kVp','55–65 kVp','90–100 kVp'].filter((v,i,a)=>a.indexOf(v)===i && v!==info.kv).slice(0,3).concat([info.kv]).sort(()=>Math.random()-0.5),
            correct:info.kv
          });
        }

        // Generate respiration question
        if(info.resp && info.resp.length>4){
          QUIZ[qKey].push({
            questionText:`For the **${pos.name}**, what is the correct respiration instruction?`,
            xrayImg:'',
            options:[info.resp,'Suspended full inspiration','Suspended expiration','Normal breathing during exposure'].filter((v,i,a)=>a.indexOf(v)===i).slice(0,4).sort(()=>Math.random()-0.5),
            correct:info.resp
          });
        }

        // Generate position type question
        QUIZ[qKey].push({
          questionText:`The **${pos.name}** in ${ch.name} is classified as:`,
          xrayImg:'',
          options:['Routine projection','Special projection','Supplemental view','Emergency-only projection'],
          correct:pos.type==='routine'?'Routine projection':'Special projection'
        });
      });
    };

    if(ch.positions) process(ch.positions, chId);
    if(ch.subchapters){
      Object.entries(ch.subchapters).forEach(([scId,sc])=>{
        process(sc.positions, `${chId}_${scId}`);
      });
    }
  });
})();

