// ── 1. STUDY MODE ──────────────────────────────
const _STUDY_KEY='bontrager_study_mode_v1';
let _studyMode=false;

function toggleStudyMode(){
  _studyMode=!_studyMode;
  document.body.classList.toggle('study-mode',_studyMode);
  const btn=document.getElementById('studyModeBtn');
  if(btn){
    btn.style.color=_studyMode?'#22c55e':'var(--text2)';
    btn.title=_studyMode?'Exit Study Mode':'Study Mode';
  }
  try{ localStorage.setItem(_STUDY_KEY,_studyMode?'1':'0'); }catch(e){}
  _showToast(_studyMode?'Study Mode ON — distractions hidden':'Study Mode OFF', _studyMode?'#15803d':'var(--text)');
}

(function _initStudyMode(){
  try{
    if(localStorage.getItem(_STUDY_KEY)==='1'){
      _studyMode=true;
      document.body.classList.add('study-mode');
      const btn=document.getElementById('studyModeBtn');
      if(btn) btn.style.color='#22c55e';
    }
  }catch(e){}
})();

// ── 2. PROGRESS TRACKING ───────────────────────
const _VIEWED_KEY='bontrager_viewed_v2';
let _viewed={};

function _loadViewed(){
  try{ const r=localStorage.getItem(_VIEWED_KEY); if(r) _viewed=JSON.parse(r); }catch(e){}
}
function _saveViewed(){
  try{ localStorage.setItem(_VIEWED_KEY,JSON.stringify(_viewed)); }catch(e){}
}
function _posViewedId(chId,scId,posIdx){
  return (scId?chId+'_'+scId:chId)+'_'+posIdx;
}
function _markViewed(chId,scId,posIdx){
  const id=_posViewedId(chId,scId,posIdx);
  if(!_viewed[id]){
    _viewed[id]=Date.now();
    _saveViewed();
  }
}
function _isViewed(chId,scId,posIdx){
  return !!_viewed[_posViewedId(chId,scId,posIdx)];
}
function _chapterProgress(chId){
  const ch=BOOK[chId]; if(!ch) return {done:0,total:0};
  let done=0,total=0;
  const addPoss=(positions,scId)=>{
    (positions||[]).forEach((p,i)=>{
      total++;
      if(_isViewed(chId,scId,i)) done++;
    });
  };
  if(ch.positions) addPoss(ch.positions,null);
  if(ch.subchapters) Object.entries(ch.subchapters).forEach(([sid,sc])=>addPoss(sc.positions,sid));
  return {done,total};
}

// Patch openPos to auto-mark viewed
const _origOpenPos=openPos;
openPos=function(pos,chId,scId,posIdx){
  _origOpenPos.apply(this,arguments);
  _markViewed(chId,scId,posIdx);
  // Show/hide viewed pill
  const pill=document.getElementById('posViewedPill');
  if(pill){
    const already=_isViewed(chId,scId,posIdx);
    pill.classList.toggle('show',already);
  }
  // Update pos btn in list
  setTimeout(()=>_refreshPosBtns(chId,scId),100);
};

function _refreshPosBtns(chId,scId){
  const list=document.getElementById('learnPosList');
  if(!list) return;
  list.querySelectorAll('.pos-btn[data-posidx]').forEach(btn=>{
    const idx=parseInt(btn.dataset.posidx);
    if(_isViewed(chId,scId,idx)){
      btn.classList.add('viewed');
    }
  });
}

_loadViewed();

// Patch buildChBtn to include progress bar
const _origBuildChBtn=buildChBtn;
buildChBtn=function(icon,name,sub,type){
  if(type!=='learn') return _origBuildChBtn(icon,name,sub,type);
  // Find chId by name
  const chId=Object.keys(BOOK).find(k=>BOOK[k].name===name);
  if(!chId) return _origBuildChBtn(icon,name,sub,type);
  const {done,total}=_chapterProgress(chId);
  const pct=total>0?Math.round(done/total*100):0;
  const progressHtml=total>0?`
    <div class="ch-progress" style="margin-top:5px">
      <div class="ch-progress-fill" style="width:${pct}%"></div>
    </div>
    <div style="display:flex;justify-content:space-between;margin-top:3px">
      <span style="font-size:10px;color:var(--text3)">${done}/${total} reviewed</span>
      <span style="font-size:10px;font-weight:700;color:${pct===100?'var(--green)':'var(--text3)'}">${pct}%</span>
    </div>`:'';
  return `<button class="ch-btn">
    <span class="ch-icon">${icon}</span>
    <div class="ch-info" style="flex:1;min-width:0">
      <div class="ch-name">${name}</div>
      <div class="ch-sub">${sub}</div>
      ${progressHtml}
    </div>
    <span class="ch-arrow"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg></span>
  </button>`;
};

