function _svgPointFromEvent(svg, ev){
  if(!svg || !ev) return null;
  const rect = svg.getBoundingClientRect();
  if(!rect.width || !rect.height) return null;
  const p = svg.viewBox && svg.viewBox.baseVal
    ? svg.viewBox.baseVal
    : {x:0,y:0,width:1000,height:1500};
  const touch = ev.changedTouches && ev.changedTouches.length ? ev.changedTouches[0]
    : (ev.touches && ev.touches.length ? ev.touches[0] : null);
  const clientX = typeof ev.clientX === 'number' ? ev.clientX : (touch && typeof touch.clientX === 'number' ? touch.clientX : null);
  const clientY = typeof ev.clientY === 'number' ? ev.clientY : (touch && typeof touch.clientY === 'number' ? touch.clientY : null);
  if(clientX === null || clientY === null) return null;
  const x = p.x + ((clientX - rect.left) / rect.width) * p.width;
  const y = p.y + ((clientY - rect.top) / rect.height) * p.height;
  return {x,y};
}

function _parsePolygonPoints(pointsStr){
  return String(pointsStr || '')
    .trim()
    .split(/\s+/)
    .map(pair=>pair.split(','))
    .filter(pair=>pair.length === 2)
    .map(pair=>({x:parseFloat(pair[0]), y:parseFloat(pair[1])}))
    .filter(pt=>Number.isFinite(pt.x) && Number.isFinite(pt.y));
}

function _pointInPolygon(point, polygon){
  const x = point.x;
  const y = point.y;
  let inside = false;
  for(let i=0, j=polygon.length-1; i<polygon.length; j=i++){
    const xi = polygon[i].x;
    const yi = polygon[i].y;
    const xj = polygon[j].x;
    const yj = polygon[j].y;
    const intersects = ((yi > y) !== (yj > y)) && (x < ((xj - xi) * (y - yi)) / ((yj - yi) || 1e-9) + xi);
    if(intersects) inside = !inside;
  }
  return inside;
}

function _distanceToSegment(px, py, x1, y1, x2, y2){
  const dx = x2 - x1;
  const dy = y2 - y1;
  if(dx === 0 && dy === 0){
    return Math.hypot(px - x1, py - y1);
  }
  const t = Math.max(0, Math.min(1, ((px - x1) * dx + (py - y1) * dy) / (dx * dx + dy * dy)));
  const cx = x1 + t * dx;
  const cy = y1 + t * dy;
  return Math.hypot(px - cx, py - cy);
}

function _distanceToPolygon(point, polygon){
  if(!polygon || polygon.length < 2) return Number.POSITIVE_INFINITY;
  if(_pointInPolygon(point, polygon)) return 0;
  let min = Number.POSITIVE_INFINITY;
  for(let i=0;i<polygon.length;i++){
    const a = polygon[i];
    const b = polygon[(i + 1) % polygon.length];
    const d = _distanceToSegment(point.x, point.y, a.x, a.y, b.x, b.y);
    if(d < min) min = d;
  }
  return min;
}

function _distanceToRect(point, rect){
  const dx = Math.max(rect.x - point.x, 0, point.x - (rect.x + rect.width));
  const dy = Math.max(rect.y - point.y, 0, point.y - (rect.y + rect.height));
  return Math.hypot(dx, dy);
}

function _pointInRect(point, rect){
  return point.x >= rect.x && point.x <= (rect.x + rect.width) && point.y >= rect.y && point.y <= (rect.y + rect.height);
}

function _distanceToRange(value, min, max){
  if(value < min) return min - value;
  if(value > max) return value - max;
  return 0;
}

function _regionGuardScore(regionId, point){
  const guard = ANATOMY_REGION_GUARDS[regionId];
  if(!guard || !Array.isArray(guard.ranges) || !guard.ranges.length) return 0;
  let insideAny = false;
  let minDistance = Number.POSITIVE_INFINITY;

  guard.ranges.forEach(range=>{
    const xRange = Array.isArray(range.x) ? range.x : [0, 0];
    const yRange = Array.isArray(range.y) ? range.y : [0, 0];
    const dx = _distanceToRange(point.x, xRange[0], xRange[1]);
    const dy = _distanceToRange(point.y, yRange[0], yRange[1]);
    const d = Math.hypot(dx, dy);
    if(d === 0) insideAny = true;
    if(d < minDistance) minDistance = d;
  });

  if(insideAny) return guard.insideBoost || 16;
  const penaltyScale = typeof guard.penaltyScale === 'number' ? guard.penaltyScale : 0.2;
  const maxPenalty = typeof guard.maxPenalty === 'number' ? guard.maxPenalty : 26;
  return -Math.min(maxPenalty, minDistance * penaltyScale);
}

function _buildAnatomyGeometry(svg){
  const regionMap = Object.create(null);
  if(!svg) return regionMap;
  svg.querySelectorAll('.skel-region[data-region]').forEach(regionEl=>{
    const regionId = regionEl.dataset.region;
    if(!regionId) return;
    const shapes = [];
    regionEl.querySelectorAll('polygon.ab-overlay, rect.ab-overlay, path.ab-overlay').forEach(shapeEl=>{
      const tag = shapeEl.tagName.toLowerCase();
      if(tag === 'path'){
        // Store reference to DOM element; hit-test via native isPointInFill
        shapes.push({type:'path', el:shapeEl});
        return;
      }
      if(tag === 'polygon'){
        const pts = _parsePolygonPoints(shapeEl.getAttribute('points'));
        if(pts.length >= 3) shapes.push({type:'polygon', points:pts});
        return;
      }
      const x = parseFloat(shapeEl.getAttribute('x') || '0');
      const y = parseFloat(shapeEl.getAttribute('y') || '0');
      const width = parseFloat(shapeEl.getAttribute('width') || '0');
      const height = parseFloat(shapeEl.getAttribute('height') || '0');
      if(Number.isFinite(x) && Number.isFinite(y) && Number.isFinite(width) && Number.isFinite(height) && width > 0 && height > 0){
        shapes.push({type:'rect', x, y, width, height});
      }
    });
    regionMap[regionId] = shapes;
  });
  return regionMap;
}

function _anatomyRegionScore(regionId, point, geometry){
  let inside = false;
  let edgeDistance = Number.POSITIVE_INFINITY;
  const shapes = geometry[regionId] || [];
  shapes.forEach(shape=>{
    if(shape.type === 'path'){
      // Use native SVG hit-testing — most accurate for curved anatomical paths
      try {
        const svgEl = shape.el.ownerSVGElement;
        if(svgEl && typeof shape.el.isPointInFill === 'function'){
          const pt = svgEl.createSVGPoint();
          pt.x = point.x;
          pt.y = point.y;
          if(shape.el.isPointInFill(pt)){
            inside = true;
            edgeDistance = 0;
          }
        }
      } catch(e){}
      return;
    }
    if(shape.type === 'polygon'){
      if(_pointInPolygon(point, shape.points)) inside = true;
      const d = _distanceToPolygon(point, shape.points);
      if(d < edgeDistance) edgeDistance = d;
      return;
    }
    if(_pointInRect(point, shape)) inside = true;
    const d = _distanceToRect(point, shape);
    if(d < edgeDistance) edgeDistance = d;
  });

  const hotspots = ANATOMY_SMART_HOTSPOTS[regionId] || [];
  let hotspotScore = 0;
  hotspots.forEach(h=>{
    const d = Math.hypot(point.x - h.x, point.y - h.y);
    const ratio = d / (h.r || 1);
    if(ratio <= 1){
      const s = (1 - ratio * ratio) * 135;
      if(s > hotspotScore) hotspotScore = s;
      return;
    }
    const s = Math.max(0, 24 - (ratio - 1) * 18);
    if(s > hotspotScore) hotspotScore = s;
  });

  const shapeScore = inside ? 125 : Math.max(0, 52 - edgeDistance * 0.24);
  const guardScore = _regionGuardScore(regionId, point);
  let total = hotspotScore + shapeScore + guardScore;

  if(regionId === 'thoracolumbar_spine' || regionId === 'cervical_spine'){
    total += Math.max(0, 28 - Math.abs(point.x - 500) * 0.2);
  }

  return {
    score: total,
    inside,
    edgeDistance,
    hotspotScore,
    guardScore
  };
}

function _resolveAnatomyRegionByPoint(point, geometry, hintedRegion){
  if(!point) return hintedRegion || null;
  const regionIds = Object.keys(ANATOMY_DATA);
  const ranked = [];

  regionIds.forEach(regionId=>{
    const sc = _anatomyRegionScore(regionId, point, geometry);
    ranked.push({regionId, ...sc});
  });

  if(!ranked.length) return hintedRegion || null;
  ranked.sort((a,b)=>b.score - a.score);
  const best = ranked[0];
  const second = ranked.length > 1 ? ranked[1] : null;

  if(hintedRegion && hintedRegion !== best.regionId){
    const hinted = ranked.find(r=>r.regionId === hintedRegion);
    if(hinted && hinted.score >= best.score - 10){
      return hintedRegion;
    }
  }

  if(second && (best.score - second.score) < 15){
    if(best.inside !== second.inside){
      return best.inside ? best.regionId : second.regionId;
    }
    if(Math.abs(best.edgeDistance - second.edgeDistance) > 3){
      return best.edgeDistance < second.edgeDistance ? best.regionId : second.regionId;
    }
    if(Math.abs(best.hotspotScore - second.hotspotScore) > 5){
      return best.hotspotScore > second.hotspotScore ? best.regionId : second.regionId;
    }
  }

  if(best.score < 70) return null;
  return best.regionId;
}

function _initSmartAnatomyHitTest(){
  const svg = document.getElementById('anatomyBodySVG');
  if(!svg) return;

  const geometry = _buildAnatomyGeometry(svg);
  let lastPointerHandledAt = 0;
  let _tapStartY = null;
  let _tapStartX = null;
  let _tapOnSVG = false;
  let _pointerDownOnSVG = false;
  let _mouseDownOnSVG = false;
  const SCROLL_TAP_THRESHOLD = 18;

  // Track whether the gesture started on the SVG (prevents accidental triggers
  // from scroll gestures that begin elsewhere and end over the SVG).
  document.addEventListener('pointerdown', function(){ _pointerDownOnSVG = false; }, true);
  document.addEventListener('mousedown', function(){ _mouseDownOnSVG = false; }, true);

  function activateRegionFromEvent(e){
    const point = _svgPointFromEvent(svg, e);
    if(!point) return;
    const regionEl = e.target && e.target.closest ? e.target.closest('[data-region]') : null;
    const hintedRegion = regionEl && regionEl.dataset ? regionEl.dataset.region : null;
    const regionId = _resolveAnatomyRegionByPoint(point, geometry, null) || hintedRegion;
    if(!regionId) return;
    e.preventDefault();
    e.stopPropagation();
    openAnatomyRegion(regionId);
  }

  svg.addEventListener('touchstart', function(e){
    _tapOnSVG = true;
    const t = e.touches && e.touches.length ? e.touches[0] : null;
    _tapStartY = t ? t.clientY : null;
    _tapStartX = t ? t.clientX : null;
  }, {capture:true, passive:true});

  svg.addEventListener('pointerdown', function(e){
    _pointerDownOnSVG = true;
    if(e.pointerType === 'touch' || e.pointerType === 'pen'){
      _tapStartY = e.clientY;
      _tapStartX = e.clientX;
    }
  }, {capture:true, passive:true});

  svg.addEventListener('mousedown', function(){
    _mouseDownOnSVG = true;
  }, {capture:true, passive:true});

  svg.addEventListener('pointerup', function(e){
    if(!_pointerDownOnSVG) return;
    if(typeof e.button === 'number' && e.button !== 0) return;
    if((e.pointerType === 'touch' || e.pointerType === 'pen') && _tapStartY !== null){
      const dy = Math.abs(e.clientY - _tapStartY);
      const dx = Math.abs(e.clientX - (_tapStartX || e.clientX));
      if(Math.hypot(dx, dy) > SCROLL_TAP_THRESHOLD) return;
    }
    lastPointerHandledAt = Date.now();
    activateRegionFromEvent(e);
  }, true);

  svg.addEventListener('mouseup', function(e){
    if(!_mouseDownOnSVG) return;
    if(typeof e.button === 'number' && e.button !== 0) return;
    lastPointerHandledAt = Date.now();
    activateRegionFromEvent(e);
  }, true);

  svg.addEventListener('touchend', function(e){
    if(!_tapOnSVG){ _tapStartY = null; return; }
    _tapOnSVG = false;
    if(_tapStartY !== null){
      const t = e.changedTouches && e.changedTouches.length ? e.changedTouches[0] : null;
      if(t){
        const dy = Math.abs(t.clientY - _tapStartY);
        const dx = Math.abs(t.clientX - (_tapStartX || t.clientX));
        if(Math.hypot(dx, dy) > SCROLL_TAP_THRESHOLD){
          _tapStartY = null;
          return;
        }
      }
    }
    _tapStartY = null;
    lastPointerHandledAt = Date.now();
    activateRegionFromEvent(e);
  }, {capture:true, passive:false});

  svg.addEventListener('click', function(e){
    if(Date.now() - lastPointerHandledAt < 450){
      e.preventDefault();
      e.stopPropagation();
      return;
    }
    if(typeof e.button === 'number' && e.button !== 0) return;
    activateRegionFromEvent(e);
  }, true);
}

function openAnatomyRegion(regionId){
  if(!ANATOMY_DATA[regionId]) return;
  buildAnatomyDetail(regionId);
  navTo('anatomy-detail');
}

function openAnatomyPos(chId, scId, posIdx){
  const ch = BOOK[chId];
  if(!ch) return;
  let positions;
  if(scId && ch.subchapters){
    const sc = ch.subchapters[scId];
    if(!sc) return;
    positions = sc.positions;
  } else if(ch.positions){
    positions = ch.positions;
  }
  if(!positions) return;
  const pos = positions[posIdx];
  if(!pos) return;
  openPos(pos, chId, scId||null, posIdx);
}

function buildAnatomyDetail(regionId){
  const r = ANATOMY_DATA[regionId];
  if(!r) return;
  const el = document.getElementById('anatDetailContent');
  if(!el) return;

  const chName = r.chapterKey && BOOK[r.chapterKey] ? BOOK[r.chapterKey].name : '';
  const chIcon = r.chapterKey && BOOK[r.chapterKey] ? BOOK[r.chapterKey].icon : '';

  const structHTML = r.structures.map(s=>`<li>${s}</li>`).join('');

  el.innerHTML = `
    <div class="anat-detail-header">
      <div class="anat-detail-icon">${r.icon}</div>
      <div>
        <div class="anat-detail-title">${r.name}</div>
        <div class="anat-detail-ar">${r.arabicName}</div>
      </div>
    </div>

    ${(()=>{
      const imgs=r.anatImages&&r.anatImages.length?r.anatImages:(r.anatImage?[r.anatImage]:[]);
      if(!imgs.length)return '';
      return imgs.map(src=>`<div class="anat-diagram-wrap" style="position:relative;cursor:zoom-in" role="button" tabindex="0" aria-label="${r.name} anatomy diagram — tap to enlarge" title="Tap to enlarge" onclick="openImgZoom(this.querySelector('img').src)" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openImgZoom(this.querySelector('img').src)}"><img src="${src}" alt="${r.name} anatomy" loading="lazy" style="pointer-events:none"/><div style="position:absolute;bottom:8px;right:10px;background:rgba(0,0,0,.55);color:#fff;font-size:10px;font-weight:600;padding:3px 8px;border-radius:20px;pointer-events:none;display:flex;align-items:center;gap:4px;backdrop-filter:blur(4px)"><svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/><line x1="11" y1="8" x2="11" y2="14"/><line x1="8" y1="11" x2="14" y2="11"/></svg> Tap to zoom</div></div>`).join('');
    })()}

    ${r.overview ? `<div class="anat-overview"><p class="anat-overview-text">${r.overview}</p></div>` : ''}

    <div class="anat-detail-section">
      <div class="anat-detail-section-title">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 3h6a4 4 0 014 4v14a3 3 0 00-3-3H2z"/><path d="M22 3h-6a4 4 0 00-4 4v14a3 3 0 013-3h7z"/></svg>
        Anatomical Structures — الهياكل التشريحية
      </div>
      <div class="anat-detail-section-body">
        <ul class="anat-struct-list">${structHTML}</ul>
      </div>
    </div>

    <div class="anat-detail-section">
      <div class="anat-detail-section-title">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="16"/><line x1="8" y1="12" x2="16" y2="12"/></svg>
        Radiographic Technique — تقنية الأشعة
      </div>
      <div class="anat-detail-section-body">
        <div class="anat-info-row">
          <div class="anat-info-label">Projections</div>
          <div class="anat-info-val">${r.radiographyNotes}</div>
        </div>
        <div class="anat-info-row">
          <div class="anat-info-label">kVp Range</div>
          <div class="anat-info-val"><span class="anat-kvp-badge">${r.kVpRange}</span></div>
        </div>
        <div class="anat-info-row">
          <div class="anat-info-label">Positioning</div>
          <div class="anat-info-val">${r.positioning}</div>
        </div>
      </div>
    </div>

    <div class="anat-detail-section">
      <div class="anat-detail-section-title">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg>
        Clinical Indications — المؤشرات السريرية
      </div>
      <div class="anat-detail-section-body">
        <div class="anat-info-val">${r.clinicalIndications}</div>
      </div>
    </div>

    ${(()=>{
      const refs = r.subchapterRefs || [];
      if(!refs.length) return '';
      let sectionsHTML = '';
      for(const {chId,scId} of refs){
        const ch = BOOK[chId];
        if(!ch) continue;
        let sc, positions;
        if(scId && ch.subchapters){
          sc = ch.subchapters[scId];
          if(!sc) continue;
          positions = sc.positions;
        } else if(ch.positions){
          sc = {name:ch.name, icon:ch.icon||'📋'};
          positions = ch.positions;
        }
        if(!positions || !positions.length) continue;
        const posCardsHTML = positions.map((pos,idx)=>{
          const isRoutine = (pos.type||'routine')==='routine';
          return `<button class="anat-pos-card" onclick="openAnatomyPos('${esc(chId)}','${esc(scId||'')}',${idx})"><span class="dot dot-${isRoutine?'r':'s'}" style="flex-shrink:0"></span><span class="anat-pos-card-name">${esc(pos.name)}</span><svg class="anat-pos-card-chevron" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg></button>`;
        }).join('');
        sectionsHTML += `<div class="anat-pos-subch"><div class="anat-pos-subch-name">${sc.icon||'📋'} ${esc(sc.name)} <span class="anat-pos-subch-count">(${positions.length})</span></div><div class="anat-pos-list">${posCardsHTML}</div></div>`;
      }
      if(!sectionsHTML) return '';
      return `<div class="anat-detail-section"><div class="anat-detail-section-title"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/></svg> Radiographic Positions — المناظر التصويرية</div><div class="anat-detail-section-body">${sectionsHTML}</div></div>`;
    })()}

    ${chName ? `<button class="anat-goto-btn" onclick="navTo('learn-chapters')">
      <span>${chIcon} Go to ${chName} chapter in Section 1 — Learn</span>
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
    </button>` : ''}
  `;
}

initAppFont();
_bindResponsiveFontSizing();
_refreshQuizBankQuality();
buildChapters();
updateStats();
_warmupOfflineImages();
// Pre-cache anatomy images in background for offline use
if(typeof requestIdleCallback === 'function'){
  requestIdleCallback(() => _warmupAnatomyImages(), {timeout:5000});
} else {
  setTimeout(_warmupAnatomyImages, 2000);
}

// Smart anatomy hit-testing + keyboard navigation.
(function(){
  var svg = document.getElementById('anatomyBodySVG');
  if(!svg) return;
  _initSmartAnatomyHitTest();
  svg.addEventListener('keydown', function(e){
    if(e.key==='Enter' || e.key===' '){
      var el = e.target && e.target.closest ? e.target.closest('[data-region]') : null;
      if(el && el.dataset && el.dataset.region){
        e.preventDefault();
        openAnatomyRegion(el.dataset.region);
      }
    }
  });
}());

